mapper.select:
SELECT COUNT(*)  >  0
FROM human_prompt_history_option
WHERE option_id = #{optionId}

SELECT hpho.prompt_history_id, hpho.person_index, hpo.name AS option_name FROM human_prompt_history_option hpho JOIN human_prompt_option hpo ON hpho.option_id = hpo.id JOIN human_prompt_attr hpa ON hpo.attr_id = hpa.id JOIN human_prompt_step hps ON hpa.step_id = hps.id WHERE hpho.prompt_history_id IN
#{id}
ORDER BY hpho.prompt_history_id ASC, hpho.person_index ASC, hps.step_number ASC, hpa.sort_order ASC, hpo.sort_order ASC
